#!/usr/bin/env python3
# SPDX-License-Identifier: AGPL-3.0-only
"""Writes tags.csv: 300 one-second rows of a receiver time tag against an onboard reference count,
with labelled injected faults (synthetic; no flight data). Deterministic: run it again and the file
is the same byte for byte.

Faults: a leap second from row 60, a 1 ms clock steer from row 120, an outlier at row 180, a
four-row gap before row 220 (rows removed), a week rollover from row 250. Clock-bias column: a
0.6 ms jump at row 200.
"""
import os

WEEK = 604800.0
rows = []
for k in range(300):
    t_ref = 5000.0 + k
    # A smooth offset: 0.5 ms plus a 2e-9 rate, with a fixed small ripple (no random numbers).
    off = 5e-4 + 2e-9 * k + 1e-9 * ((k * 7) % 5 - 2)
    if k >= 60:
        off += 1.0
    if k >= 120:
        off -= 1e-3
    if k == 180:
        off += 2e-4
    if k >= 250:
        off -= 1024 * WEEK
    bias = 1e-4 if k < 200 else 7e-4
    rows.append((t_ref, t_ref + 1_400_000_000.0 + off, bias))
rows = [r for i, r in enumerate(rows) if not (216 <= i < 220)]
out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tags.csv")
with open(out, "w") as f:
    f.write("# synthetic, generated by gen_fixture.py; labelled faults in its docstring\n")
    f.write("t_ref_s,t_rx_s,clock_bias_s\n")
    for t_ref, t_rx, bias in rows:
        f.write("%.1f,%.10f,%.6e\n" % (t_ref, t_rx, bias))
